const parsed = $input.first().json.output;
const weight = parsed.weightGram || 0;
const hours = parsed.durationHours || 0;
const isCustomerFilament = parsed.isCustomerFilament || false;
const materialRate = isCustomerFilament ? 0 : (parsed.filamentRate || 800);
const materialCost = weight * materialRate;

let machineCost = 0;
if (hours > 0) {
  machineCost = hours <= 1 ? hours * 10000 : 10000 + (hours - 1) * 2640;
}

let addonsTotal = 0;
const itemizedTable = [];
itemizedTable.push({
  item: `Jasa Cetak 3D (${weight}g, ${hours} Jam)`,
  qty: 1,
  price: Math.round(materialCost + machineCost),
  subtotal: Math.round(materialCost + machineCost)
});

if (parsed.addons && parsed.addons.length > 0) {
  parsed.addons.forEach(add => {
    const sub = add.qty * add.pricePerItem;
    addonsTotal += sub;
    itemizedTable.push({ item: add.item, qty: add.qty, price: add.pricePerItem, subtotal: sub });
  });
}

const grandTotal = Math.round(materialCost + machineCost + addonsTotal);
const formatIDR = (num) => "Rp" + num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");

return {
  clientName: parsed.clientName || "Customer",
  projectName: parsed.projectName || "3D Print Project",
  details: itemizedTable,
  summary: {
    materialCost: formatIDR(materialCost),
    machineCost: formatIDR(machineCost),
    addonsTotal: formatIDR(addonsTotal),
    grandTotal: formatIDR(grandTotal),
    rawGrandTotal: grandTotal
  }
};

const data = $input.first().json;
let tableRows = "";
data.details.forEach((row, idx) => {
  const bg = idx % 2 === 0 ? "#14171f" : "#1a1e29";
  tableRows += `
    <tr style="background-color: ${bg};">
      <td style="padding: 12px 10px; text-align: center; border-bottom: 1px solid #262b38; color: #9ca3af;">${idx + 1}</td>
      <td style="padding: 12px 10px; border-bottom: 1px solid #262b38; color: #f3f4f6; font-weight: 500;">${row.item}</td>
      <td style="padding: 12px 10px; text-align: center; border-bottom: 1px solid #262b38; color: #9ca3af;">${row.qty}</td>
      <td style="padding: 12px 10px; text-align: right; border-bottom: 1px solid #262b38; color: #9ca3af;">Rp${row.price.toLocaleString('id-ID')}</td>
      <td style="padding: 12px 10px; text-align: right; border-bottom: 1px solid #262b38; color: #ef4444; font-weight: 700;">Rp${row.subtotal.toLocaleString('id-ID')}</td>
    </tr>
  `;
});

const today = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
const invNo = `INV-${Math.floor(10000 + Math.random() * 90000)}`;

const htmlInvoice = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>@page { size: A4; margin: 0; } body { font-family: sans-serif; color: #e5e7eb; margin: 0; padding: 40px; background: #0d0e12; } .container { max-width: 800px; margin: 0 auto; } .header { display: flex; justify-content: space-between; align-items: center; } .brand-title { font-size: 22px; font-weight: 800; color: #fff; } .brand-title span { color: #ef4444; } .invoice-title { font-size: 32px; font-weight: 900; color: #ef4444; text-align: right; } .divider { height: 2px; background: #ef4444; margin: 20px 0; } .meta-grid { display: flex; justify-content: space-between; background: #14171f; padding: 20px; border-radius: 8px; margin-bottom: 20px; } table { width: 100%; border-collapse: collapse; margin-bottom: 25px; } th { background: #1a1e29; color: #fff; padding: 12px 10px; text-align: left; } .grand-total-box { background: #ef4444; color: #fff; padding: 12px 24px; font-weight: 800; font-size: 16px; border-radius: 6px; float: right; }</style></head><body><div class="container"><div class="header"><div><div class="brand-title">ProtoPrime <span>3D</span></div></div><div><div class="invoice-title">INVOICE</div></div></div><div class="divider"></div><div class="meta-grid"><div><p style="color:#ef4444;font-weight:bold;">INVOICE TO:</p><h3>${data.clientName}</h3><p>Project: ${data.projectName}</p></div><div style="text-align:right;"><h3 style="color:#ef4444;">${invNo}</h3><p>Tanggal: ${today}</p></div></div><table><thead><tr><th>NO</th><th>DESKRIPSI PROYEK</th><th>QTY</th><th style="text-align:right;">HARGA</th><th style="text-align:right;">TOTAL</th></tr></thead><tbody>${tableRows}</tbody></table><div class="grand-total-box"><span>TOTAL BAYAR: ${data.summary.grandTotal}</span></div></div></body></html>`;

return { htmlInvoice };
